-- Piano MINI CUT (tipo cut), da eseguire in Supabase > SQL Editor dopo setup_piani.sql.
-- Si collega alla fase di tipo cut più recente del Setup (se non ce n'è ancora una resta scollegato: collegalo dopo con
--   update public.meal_plans set phase_id = <id fase> where name = 'Mini cut';)
-- e risulta come variante del piano bulk ricalibrato, così il confronto «Cosa cambia» funziona. Si può eseguire più volte.
do $$
declare ph bigint; b bigint;
begin
  if exists (select 1 from public.meal_plans where name = 'Mini cut') then return; end if;
  select id into ph from public.phases where phase_type = 'cut' order by start_date desc limit 1;
  select id into b from public.meal_plans where name = 'Ricalibrato' and phase_type = 'bulk' order by version desc limit 1;
  insert into public.meal_plans (phase_id, phase_type, name, version, status, replaces_id, targets, meals, days, notes)
  values (ph, 'cut', 'Mini cut', 1, 'active', b, $j${"kg":79,"protein_per_kg":2,"fat_per_kg":0.7}$j$::jsonb, $j$[["pre","Pre-allenamento","03:30"],["col","Colazione / post-allenamento","05:40"],["sm","Spuntino mattina","09:30"],["pra","Pranzo","13:00"],["sp","Spuntino pomeriggio","16:30"],["cena","Cena","20:00"]]$j$::jsonb, $j$[{"nome":"Lunedì","tgt":{"kcal":2200,"tipo":"Pesi"},"meals":{"pre":[{"f":"dattero","n":1},{"f":"caffe","n":1}],"col":[{"head":"Porridge"},{"f":"avena","n":30},{"f":"yogurt","n":140},{"f":"soia","n":120},{"f":"chia","n":10},{"f":"burro","n":5},{"f":"cacao","n":5},{"f":"whey","n":30},{"f":"frutto","n":1}],"sm":[{"f":"whey","n":25},{"f":"frutto","n":1}],"sp":[{"f":"yogurt","n":160},{"f":"wasa","n":1},{"f":"frutto","n":1}],"pra":[{"f":"pasta_int","n":60},{"f":"ceci","n":165},{"f":"verdura","n":200},{"f":"olio","n":4}],"cena":[{"f":"salmone","n":160},{"f":"segale","n":55},{"f":"avocado","n":45},{"f":"verdura","n":200}]}},{"nome":"Martedì","tgt":{"kcal":2200,"tipo":"Pesi"},"meals":{"pre":[{"f":"dattero","n":1},{"f":"caffe","n":1}],"col":[{"head":"Porridge"},{"f":"avena","n":30},{"f":"yogurt","n":140},{"f":"soia","n":120},{"f":"chia","n":10},{"f":"burro","n":5},{"f":"cacao","n":5},{"f":"whey","n":30},{"f":"frutto","n":1}],"sm":[{"f":"whey","n":25},{"f":"frutto","n":1}],"sp":[{"f":"yogurt","n":160},{"f":"wasa","n":1},{"f":"frutto","n":1}],"pra":[{"f":"riso","n":55},{"f":"ceci","n":200},{"f":"verdura","n":200},{"f":"olio","n":9}],"cena":[{"f":"uovo","n":2},{"f":"albume","n":145},{"f":"segale","n":30},{"f":"avocado","n":85},{"f":"verdura","n":200}]}},{"nome":"Mercoledì","tgt":{"kcal":2200,"tipo":"Pesi"},"meals":{"pre":[{"f":"dattero","n":1},{"f":"caffe","n":1}],"col":[{"head":"Porridge"},{"f":"avena","n":30},{"f":"yogurt","n":140},{"f":"soia","n":120},{"f":"chia","n":10},{"f":"burro","n":5},{"f":"cacao","n":5},{"f":"whey","n":30},{"f":"frutto","n":1}],"sm":[{"f":"whey","n":25},{"f":"frutto","n":1}],"sp":[{"f":"yogurt","n":160},{"f":"wasa","n":1},{"f":"frutto","n":1}],"pra":[{"f":"pasta_farro","n":60},{"f":"ceci","n":190},{"f":"verdura","n":200},{"f":"olio","n":3}],"cena":[{"f":"sgombro","n":165},{"f":"wasa","n":3},{"f":"avocado","n":45},{"f":"verdura","n":200}]}},{"nome":"Giovedì","tgt":{"kcal":2200,"tipo":"Pesi"},"meals":{"pre":[{"f":"dattero","n":1},{"f":"caffe","n":1}],"col":[{"head":"Porridge"},{"f":"avena","n":30},{"f":"yogurt","n":140},{"f":"soia","n":120},{"f":"chia","n":10},{"f":"burro","n":5},{"f":"cacao","n":5},{"f":"whey","n":30},{"f":"frutto","n":1}],"sm":[{"f":"whey","n":25},{"f":"frutto","n":1}],"sp":[{"f":"yogurt","n":160},{"f":"wasa","n":1},{"f":"frutto","n":1}],"pra":[{"f":"riso","n":55},{"f":"ceci","n":155},{"f":"verdura","n":200},{"f":"olio","n":4}],"cena":[{"f":"salmone","n":175},{"f":"segale","n":55},{"f":"avocado","n":40},{"f":"verdura","n":200}]}},{"nome":"Venerdì","tgt":{"kcal":2200,"tipo":"Pesi"},"meals":{"pre":[{"f":"dattero","n":1},{"f":"caffe","n":1}],"col":[{"head":"Porridge"},{"f":"avena","n":30},{"f":"yogurt","n":140},{"f":"soia","n":120},{"f":"chia","n":10},{"f":"burro","n":5},{"f":"cacao","n":5},{"f":"whey","n":30},{"f":"frutto","n":1}],"sm":[{"f":"whey","n":25},{"f":"frutto","n":1}],"sp":[{"f":"yogurt","n":160},{"f":"wasa","n":1},{"f":"frutto","n":1}],"pra":[{"f":"pasta_int","n":45},{"f":"ceci","n":195},{"f":"verdura","n":200},{"f":"olio","n":10}],"cena":[{"f":"uovo","n":2},{"f":"albume","n":130},{"f":"wasa","n":5},{"f":"avocado","n":65},{"f":"verdura","n":200}]}},{"nome":"Sabato","tgt":{"kcal":2200,"tipo":"Pesi"},"meals":{"pre":[{"f":"dattero","n":1},{"f":"caffe","n":1}],"col":[{"head":"Porridge"},{"f":"avena","n":30},{"f":"yogurt","n":140},{"f":"soia","n":120},{"f":"chia","n":10},{"f":"burro","n":5},{"f":"cacao","n":5},{"f":"whey","n":30},{"f":"frutto","n":1}],"sm":[{"f":"whey","n":25},{"f":"frutto","n":1}],"sp":[{"f":"yogurt","n":160},{"f":"wasa","n":1},{"f":"frutto","n":1}],"pra":[{"f":"segale","n":65},{"f":"ceci","n":205},{"f":"verdura","n":200},{"f":"olio","n":2}],"cena":[{"f":"sgombro","n":165},{"f":"segale","n":50},{"f":"avocado","n":40},{"f":"verdura","n":200}]}},{"nome":"Domenica","tgt":{"kcal":2000,"tipo":"Corsa (cardio)"},"pre":"Pre-corsa","meals":{"pre":[{"f":"banana","n":1},{"f":"caffe","n":1}],"col":[{"head":"Porridge"},{"f":"avena","n":35},{"f":"yogurt","n":140},{"f":"soia","n":120},{"f":"chia","n":10},{"f":"burro","n":5},{"f":"cacao","n":5},{"f":"whey","n":25},{"f":"mela","n":1}],"sm":[{"f":"yogurt","n":170},{"f":"mela","n":1}],"pra":[{"f":"ceci","n":210},{"f":"segale","n":50},{"f":"verdura","n":200},{"f":"olio","n":2}],"sp":[{"f":"whey","n":30},{"f":"wasa","n":1}],"cena":[{"f":"salmone","n":155},{"f":"wasa","n":1},{"f":"avocado","n":65},{"f":"verdura","n":200}]}}]$j$::jsonb, 'Mini cut: circa 300 kcal in meno rispetto al bulk (2200 nei giorni di pesi, 2000 la domenica). Proteine invariate a 2 g/kg, grassi 0,7 g/kg; i carboidrati scendono soprattutto da pasta, riso, pane e Wasa.');
end $$;
